stock=0
future_lost=0
first_stockout=None
for e in sorted(future,key=lambda x:(x["event_time"],x["event_id"])):
    if e["kind"]=="receipt":
        stock += e["quantity"]
    else:
        unmet=max(0,e["quantity"]-stock)
        if unmet>0 and first_stockout is None:
            first_stockout=e["event_time"]
        future_lost += unmet
        stock -= min(stock,e["quantity"])
stock, future_lost, first_stockout
